#define CTL_SCROLLBAR { 0xffff, 0x84 }
#define CTL_BUTTON { 0xffff, 0x80 }

template<size_t FontLength>
struct DLGTEMPLATEEX_HEADER {
    WORD      dlgVer;
    WORD      signature;
    DWORD     helpID;
    DWORD     exStyle;
    DWORD     style;
    WORD      cDlgItems;
    SIZEPOS   sizePos;
    WORD      menu;        // unused, only 0000
    WORD      windowClass; // ditto
    WCHAR     title[10 - FontLength]; // Pad with spaces when using CJK fonts with shorter name, to make the header sizes equal
    WORD      pointsize;
    WORD      weight;
    BYTE      italic;
    BYTE      charset;
    WCHAR     typeface[FontLength]; // L"Segoe UI" (9), L"맑은 고딕" (6), L"微軟正黑體" (6), L"游ゴシック" (6), L"メイリオ" (5), or L"微软雅黑" (5)
};

